#!/usr/bin/env node
/**
 * Download the upstream Vega / Vega-Lite example specs the chart wizard builds on, verbatim, and write
 * them to editor/static/chart-templates.js (shared byte-for-byte with md-doc-pipeline's studio).
 *
 *   node scripts/chart-upstream.mjs            fetch every spec listed below and regenerate the file
 *   node scripts/chart-upstream.mjs --check    verify the generated file still equals upstream (network)
 *
 * The wizard never edits a template beyond filling in the user's data and renaming the example's field
 * names to the user's columns (see ChartCatalog.fill). Sources: github.com/vega/vega-lite and
 * github.com/vega/vega, BSD-3-Clause (Copyright (c) 2015, University of Washington Interactive Data Lab).
 */
import { writeFileSync, readFileSync } from 'node:fs';

const VL = 'https://raw.githubusercontent.com/vega/vega-lite/main/examples/specs/';
const VG = 'https://raw.githubusercontent.com/vega/vega/main/docs/examples/';
// key: file under the repo's examples folder
export const VEGA_LITE = [
	'bar', 'point_2d', 'point_bubble', 'line', 'line_step', 'area', 'stacked_area', 'stacked_area_normalize', 'stacked_area_stream',
	'line_slope', 'window_rank', 'layer_ranged_dot', 'facet_bullet', 'waterfall_chart', 'bar_diverging_stack_population_pyramid', 'rect_mosaic_labelled_with_offset', 'bar_gantt',
	'area_cumulative_freq', 'layer_line_rolling_mean_point_raw', 'layer_dual_axis', 'layer_candlestick', 'area_horizon', 'trellis_bar_histogram', 'circle_wilkinson_dotplot',
	'area_density', 'area_density_stacked', 'area_density_facet', 'boxplot_2D_vertical', 'tick_strip', 'layer_point_errorbar_ci', 'layer_line_errorband_ci',
	'point_quantile_quantile', 'layer_point_line_regression', 'layer_point_line_loess', 'connected_scatterplot', 'parallel_coordinate', 'layer_text_heatmap',
	'rect_binned_heatmap', 'arc_radial', 'interactive_splom',
	'arc_pie', 'arc_donut', 'rect_heatmap', 'histogram', 'bar_aggregate', 'bar_grouped', 'stacked_bar_h', 'stacked_bar_normalize', 'layer_bar_labels',
];
export const VEGA = [
	'treemap', 'sunburst', 'circle-packing', 'tree-layout', 'radial-tree-layout', 'radar-chart', 'word-cloud', 'calendar-view', 'violin-plot', 'contour-plot',
	'edge-bundling', 'force-directed-layout', 'arc-diagram',
];

const OUT = new URL('../editor/static/chart-templates.js', import.meta.url);

async function get(url) {
	const res = await fetch(url);
	if (!res.ok) throw new Error(`${url}: HTTP ${res.status}`);
	return res.json();
}

export async function fetchAll() {
	const out = {};
	for (const n of VEGA_LITE) out[`vega-lite/${n}`] = { src: `vega-lite/examples/specs/${n}.vl.json`, spec: await get(`${VL}${n}.vl.json`) };
	for (const n of VEGA) out[`vega/${n}`] = { src: `vega/docs/examples/${n}.vg.json`, spec: await get(`${VG}${n}.vg.json`) };
	return out;
}

const render = (all) => `/*
 * Upstream Vega / Vega-Lite example specs, verbatim. GENERATED by scripts/chart-upstream.mjs - do not edit.
 * Sources: github.com/vega/vega-lite and github.com/vega/vega (BSD-3-Clause,
 * Copyright (c) 2015, University of Washington Interactive Data Lab).
 * Shared byte-for-byte with md-doc-pipeline's studio.
 */
(function (root) {
	'use strict';
	root.ChartCatalog.TEMPLATES = ${JSON.stringify(all, null, '\t').replace(/\n/g, '\n\t')};
})(typeof window !== 'undefined' ? window : globalThis);
`;

if (process.argv[1] === new URL(import.meta.url).pathname) {
	const all = await fetchAll();
	if (process.argv.includes('--check')) {
		const now = readFileSync(OUT, 'utf8');
		if (now !== render(all)) { console.error('chart-templates.js differs from upstream: run node scripts/chart-upstream.mjs'); process.exit(1); }
		console.log(`${Object.keys(all).length} templates match upstream`);
	} else {
		writeFileSync(OUT, render(all));
		console.log(`wrote ${Object.keys(all).length} templates`);
	}
}
